import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class Main {
    static final int[] OPPOSITE = {5, 3, 4, 1, 2, 0};

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        while (line != null && line.trim().isEmpty()) {
            line = br.readLine();
        }
        if (line == null) return;

        int n = Integer.parseInt(line.trim());
        int[][] dice = new int[n][6];

        for (int i = 0; i < n; i++) {
            line = br.readLine();
            while (line != null && line.trim().isEmpty()) {
                line = br.readLine();
            }
            if (line == null) break;
            StringTokenizer st = new StringTokenizer(line);
            for (int j = 0; j < 6; j++) {
                dice[i][j] = Integer.parseInt(st.nextToken());
            }
        }

        int maxSum = 0;

        // Tenta cada uma das 6 faces do dado da base como face inferior
        for (int bottomFaceIdx = 0; bottomFaceIdx < 6; bottomFaceIdx++) {
            int currentBottomValue = dice[0][bottomFaceIdx];
            int currentSum = 0;

            for (int i = 0; i < n; i++) {
                // Encontra a face com o valor currentBottomValue no dado i
                int bottomIdx = -1;
                for (int j = 0; j < 6; j++) {
                    if (dice[i][j] == currentBottomValue) {
                        bottomIdx = j;
                        break;
                    }
                }

                int topIdx = OPPOSITE[bottomIdx];
                int topValue = dice[i][topIdx];

                // O maior valor lateral é o maior valor entre 1 e 6 que não seja nem base nem topo
                int maxSide = 6;
                if (currentBottomValue == 6 || topValue == 6) {
                    maxSide = 5;
                    if (currentBottomValue == 5 || topValue == 5) {
                        maxSide = 4;
                    }
                }

                currentSum += maxSide;
                currentBottomValue = topValue;
            }

            if (currentSum > maxSum) {
                maxSum = currentSum;
            }
        }

        System.out.println(maxSum);
    }
}
